<?php
session_start();include 'conn.php';include 'auth.php';require_roles(['forestry_officer','owner']);if(!isset($_POST['save']))redirect('plantations.php');
$id=(int)($_POST['plantation_id']??0);$owner=(int)($_POST['owner_id']??0);$request_id=(int)($_POST['plant_request_id']??0);$name=db_escape($con,$_POST['plantation_name']??'');$district=db_escape($con,$_POST['district']??'');$sector=db_escape($con,$_POST['sector']??'');$lat=(float)($_POST['latitude']??0);$lng=(float)($_POST['longitude']??0);$area=(float)($_POST['area_size']??0);$uid=(int)$_SESSION['user_id'];mysqli_begin_transaction($con);
if($_SESSION['role']==='owner'){$owner=$uid;$id=0;$r=mysqli_query($con,"SELECT fr.*,tt.unit_price FROM forest_requests fr JOIN tree_types tt ON tt.tree_type_id=fr.tree_type_id WHERE fr.request_id=$request_id AND fr.requester_id=$uid AND fr.request_type='plant_license' AND fr.status='approved' AND fr.fulfillment_status='awaiting_registration' FOR UPDATE");$req=$r?mysqli_fetch_assoc($r):null;$area=(float)($req['area_size']??0);}else $req=null;
if(!$name||!$district||!$sector||$area<=0||$lat< -90||$lat>90||$lng< -180||$lng>180||($_SESSION['role']==='owner'&&!$req)){flash('danger','Provide valid plantation details and an unused planting approval.');redirect($_SESSION['role']==='owner'?"plantation_form.php?request_id=$request_id":'plantation_form.php');}
if($id)$ok=mysqli_query($con,"UPDATE plantations SET owner_id=$owner,plantation_name='$name',district='$district',sector='$sector',latitude=$lat,longitude=$lng,area_size=$area WHERE plantation_id=$id");
else{$ok=mysqli_query($con,"INSERT INTO plantations(owner_id,plantation_name,district,sector,latitude,longitude,area_size,plant_request_id) VALUES($owner,'$name','$district','$sector',$lat,$lng,$area,".($request_id?:'NULL').")");$id=(int)mysqli_insert_id($con);}
if($ok&&$req){$type=(int)$req['tree_type_id'];$species=db_escape($con,$req['species']);$qty=(int)$req['quantity'];$price=(float)$req['unit_price'];$ok=mysqli_query($con,"INSERT INTO trees(plantation_id,tree_type_id,species,quantity,age_years,growth_status,unit_price,estimated_value) VALUES($id,$type,'$species',$qty,0,'seedling',$price,$qty*$price)");if($ok)$ok=mysqli_query($con,"UPDATE forest_requests SET fulfillment_status='completed',completed_at=NOW() WHERE request_id=$request_id AND fulfillment_status='awaiting_registration'");}
if($ok){mysqli_commit($con);audit($con,$uid,'plantation_registered','plantation',$id,$req?'Created from approved planting request':'Record updated');}else mysqli_rollback($con);
flash($ok?'success':'danger',$ok?'Plantation and planted stock saved.':'Could not save plantation.');redirect('plantations.php');
?>
